variables.secs:
{%- set W = {'a':1,'an':1,'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'seven':7,'eight':8,'nine':9,'ten':10,'eleven':11,'twelve':12,'thirteen':13,'fourteen':14,'fifteen':15,'sixteen':16,'seventeen':17,'eighteen':18,'nineteen':19,'twenty':20,'thirty':30,'forty':40,'fifty':50,'sixty':60,'ninety':90} -%}
{%- set t = ((trigger.slots.duration | default('')) | lower | replace('-', ' ') | regex_replace('[^a-z0-9.: ]', ' ')) -%}
{%- set ns = namespace(out=[], prev=none) -%}
{%- for w in t.split() -%}
  {%- if w in W -%}
    {%- set v = W[w] -%}
    {%- if ns.prev is not none and ns.prev >= 20 and ns.prev % 10 == 0 and v < 10 -%}
      {%- set ns.out = ns.out[:-1] + [(ns.prev + v) | string] -%}{%- set ns.prev = none -%}
    {%- else -%}{%- set ns.out = ns.out + [v | string] -%}{%- set ns.prev = v -%}{%- endif -%}
  {%- else -%}{%- set ns.out = ns.out + [w] -%}{%- set ns.prev = none -%}{%- endif -%}
{%- endfor -%}
{%- set s = ns.out | join(' ') -%}
{%- set s = s | regex_replace('\\b(1 )?quarter (of )?(an |1 )?hour', '15 minutes') | regex_replace('\\b1 half (an|1) hour', '30 minutes') | regex_replace('\\bhalf (an|1) hour', '30 minutes') | regex_replace('\\bhalf (a|1) minute', '30 seconds') -%}
{%- set s = s | regex_replace('(\\d+(?:\\.\\d+)?) and (1|a) half (hours?|hrs?|minutes?|mins?)', '\\1.5 \\3') | regex_replace('(\\d+) (hours?|hrs?|minutes?|mins?) and (1|a) half', '\\1.5 \\2') -%}
{%- set ns2 = namespace(sec=0) -%}
{%- for m in s | regex_findall('(\\d+(?:\\.\\d+)?)\\s*(hours?|hrs?|h\\b|minutes?|mins?|m\\b|seconds?|secs?|s\\b)') -%}
  {%- set n = m[0] | float -%}
  {%- set u = m[1][0] -%}
  {%- set ns2.sec = ns2.sec + n * (3600 if u == 'h' else 60 if u == 'm' else 1) -%}
{%- endfor -%}
{{ ns2.sec | int }}

variables.when:
{%- set W = {'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'seven':7,'eight':8,'nine':9,'ten':10,'eleven':11,'twelve':12,'thirteen':13,'fourteen':14,'fifteen':15,'sixteen':16,'seventeen':17,'eighteen':18,'nineteen':19,'twenty':20,'thirty':30,'forty':40,'fifty':50,'oh':0,'o':0} -%}
{%- set t = ((trigger.slots.time | default('')) | lower | replace('a.m.', 'am') | replace('p.m.', 'pm') | replace('-', ' ') | regex_replace('[^a-z0-9: ]', ' ')) -%}
{%- set t = t | regex_replace('\\b(\\d{1,2})\\s*(am|pm)\\b', '\\1 \\2') | regex_replace("o ?clock", " ") -%}
{%- set ns = namespace(out=[], prev=none) -%}
{%- for w in t.split() -%}
  {%- if w in W -%}
    {%- set v = W[w] -%}
    {%- if ns.prev is not none and ns.prev >= 20 and ns.prev % 10 == 0 and v < 10 -%}
      {%- set ns.out = ns.out[:-1] + [(ns.prev + v) | string] -%}{%- set ns.prev = none -%}
    {%- else -%}{%- set ns.out = ns.out + [v | string] -%}{%- set ns.prev = v -%}{%- endif -%}
  {%- else -%}{%- set ns.out = ns.out + [w] -%}{%- set ns.prev = none -%}{%- endif -%}
{%- endfor -%}
{%- set s = ' ' ~ (ns.out | join(' ') | replace('noon', '12 pm') | replace('midnight', '12 am')) ~ ' ' -%}
{%- set mer = 'pm' if (' pm ' in s or 'evening' in s or 'tonight' in s or 'afternoon' in s or 'at night' in s) else 'am' if (' am ' in s or 'morning' in s or 'wake' in (trigger.sentence | lower)) else '' -%}
{%- set h = none -%}{%- set mi = 0 -%}
{%- set q = s | regex_findall('(half|quarter|\\d{1,2}) (past|after|to) (\\d{1,2})') -%}
{%- if q -%}
  {%- set a = 30 if q[0][0] == 'half' else 15 if q[0][0] == 'quarter' else q[0][0] | int -%}
  {%- set hb = q[0][2] | int -%}
  {%- set h = hb if q[0][1] != 'to' else (hb - 1 if hb > 1 else 12) -%}
  {%- set mi = a if q[0][1] != 'to' else 60 - a -%}
{%- else -%}
  {%- set m = s | regex_findall('\\b(\\d{1,2})(?:[: ](\\d{1,2}))?\\b') -%}
  {%- if m -%}{%- set h = m[0][0] | int -%}{%- set mi = (m[0][1] or 0) | int -%}{%- endif -%}
{%- endif -%}
{%- if h is none or h > 23 or mi > 59 -%}none
{%- else -%}
  {%- set n = now() -%}
  {%- if mer == 'pm' and h < 12 -%}{%- set cands = [h + 12] -%}
  {%- elif mer == 'am' -%}{%- set cands = [0 if h == 12 else h] -%}
  {%- elif h >= 13 or h == 0 -%}{%- set cands = [h] -%}
  {%- else -%}{%- set cands = [h % 12, h % 12 + 12] -%}{%- endif -%}
  {%- set ns3 = namespace(best=none) -%}
  {%- for hh in cands -%}
    {%- set c = n.replace(hour=hh, minute=mi, second=0, microsecond=0) -%}
    {%- if c <= n -%}{%- set c = c + timedelta(days=1) -%}{%- endif -%}
    {%- if ns3.best is none or c < ns3.best -%}{%- set ns3.best = c -%}{%- endif -%}
  {%- endfor -%}
  {{ ns3.best.strftime('%Y-%m-%d %H:%M:%S') }}
{%- endif -%}
